contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint extraAmount) public payable {
        require(depositAmount > 0);
        require(extraAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();

        uint creditBefore = c.credit(address(this));
        uint balanceBefore = address(c).balance;

        // Drain the contract's Ether so it cannot cover the caller's credit.
        // The test contract is the only depositor, so its own credit still
        // remains in storage while the contract's actual balance is reduced.
        (bool drainOk, ) = address(c).call{value: balanceBefore - extraAmount}("");
        require(drainOk);

        uint balanceBeforeWithdraw = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint creditAfter = c.credit(address(this));
        uint balanceAfter = address(c).balance;

        assert(
            reverted
                ? (creditAfter == creditBefore && balanceAfter == balanceBeforeWithdraw)
                : (creditAfter == 0 && balanceAfter == balanceBeforeWithdraw - creditBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
