    function run(uint depositAmount, uint extraAmount) public payable {
        require(depositAmount > 0);
        require(extraAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();

        uint balanceBefore = address(c).balance;
        uint leftover = balanceBefore - extraAmount;

        (bool drainOk, ) = address(c).call{value: leftover}("");
        require(drainOk);

        uint balanceBeforeWithdraw = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        // The caller's credited amount is exactly depositAmount and cannot be read directly,
        // so we infer it from the fact that the insufficient-balance setup was reached:
        // balanceBeforeWithdraw < depositAmount.  If withdrawAll reverted, no Ether moved
        // and the credit is still depositAmount.
        assert(
            balanceBeforeWithdraw < depositAmount
                ? (reverted && balanceAfter == balanceBeforeWithdraw)
                : true
        );
    }

    receive() external payable {}
}

